// Render the promo and write the web-ready files used by the landing page:
//   ../public/promo.mp4         H.264 + AAC, 1080x1920, 30 fps, faststart
//   ../public/promo-poster.jpg  end-card frame (logo fully visible)
//
// Audio: voiceover.wav (Kokoro af_heart) over an original CC0 music bed generated by
// scripts/music.mjs. The music is sidechain-ducked under the voice, then the mix is
// normalized to about -14 LUFS.
//
// Usage: node scripts/build.mjs   (run scripts/tts.mjs, transcribe.mjs, make-transcript.mjs first
// if the voiceover changed)
import { execFileSync } from "node:child_process"
import { mkdirSync, readFileSync, statSync } from "node:fs"

const root = new URL("..", import.meta.url).pathname
const pub = `${root}../public`
const run = (cmd, args) => execFileSync(cmd, args, { cwd: root, stdio: "inherit" })
mkdirSync(`${root}out`, { recursive: true })
mkdirSync(pub, { recursive: true })

const { duration } = JSON.parse(readFileSync(`${root}src/words.json`, "utf8"))
const fadeOutStart = Math.max(0, duration - 1.5)

// 0. Original music bed, synthesized from the voiceover cues.
run("node", ["scripts/music.mjs"])

// 1. High-quality silent master from Remotion.
run("npx", ["remotion", "render", "src/index.ts", "Promo", "out/promo-raw.mp4", "--muted", "--crf=12"])

// 2. Web encode + mix.
//    - voice: normalized to -16 LUFS, split so it can also key the ducker
//    - music: -4 dB base, 0.5 s fade-in and 1.5 s fade-out
//    - sidechaincompress pulls the music ~18 dB under the voice while she speaks
//    - final loudnorm lands the program at about -14 LUFS
const mix = [
  "[1:a]aresample=48000,pan=stereo|c0=c0|c1=c0,loudnorm=I=-16:TP=-1.5:LRA=9,aresample=48000,asplit=2[voice][key]",
  `[2:a]aresample=48000,volume=-4dB,afade=t=in:st=0:d=0.5,afade=t=out:st=${fadeOutStart}:d=1.5[music]`,
  "[music][key]sidechaincompress=threshold=0.02:ratio=20:attack=8:release=320:makeup=1[ducked]",
  "[ducked][voice]amix=inputs=2:duration=longest:normalize=0,loudnorm=I=-14:TP=-1.5:LRA=11[a]",
].join(";")

run("ffmpeg", [
  "-y", "-loglevel", "error",
  "-i", "out/promo-raw.mp4",
  "-i", "voiceover.wav",
  "-i", "out/music.wav",
  "-filter_complex", mix,
  "-map", "0:v", "-map", "[a]",
  "-c:v", "libx264", "-preset", "slow", "-crf", "23", "-profile:v", "high", "-pix_fmt", "yuv420p", "-r", "30",
  "-c:a", "aac", "-b:a", "128k", "-ar", "48000", "-ac", "2",
  "-shortest", "-movflags", "+faststart",
  `${pub}/promo.mp4`,
])

// 3. Poster = end-card frame, where the logo is fully visible and holding.
const posterFrame = Math.round(duration * 30) - 24
run("npx", ["remotion", "still", "src/index.ts", "Promo", "out/poster.png", `--frame=${posterFrame}`])
run("ffmpeg", ["-y", "-loglevel", "error", "-i", "out/poster.png", "-q:v", "4", `${pub}/promo-poster.jpg`])

for (const f of ["promo.mp4", "promo-poster.jpg"]) {
  console.log(`${f}: ${(statSync(`${pub}/${f}`).size / 1024).toFixed(0)} KB`)
}
